    private static Object hold()throws Exception{Map<?,?> holds=(Map<?,?>)((Map<?,?>)field(VehicleCouplingTransfer.class,"HOLDS")).get(world);need(holds!=null&&holds.size()==1,"one actual WAL");return holds.values().iterator().next();}
    private static File file(WorldServer w){return new File(w.getSaveHandler().getWorldDirectory(),"scoped-split-fixture.nbt");}
    private static NBTTagCompound read(File f)throws IOException{try(InputStream in=new FileInputStream(f)){return CompressedStreamTools.readCompressed(in);}}
    private static void write(WorldServer w,NBTTagCompound n)throws IOException{File f=file(w);ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(n,bytes);Path target=f.toPath(),temp=target.resolveSibling(f.getName()+".tmp");try(FileOutputStream out=new FileOutputStream(temp.toFile())){out.write(bytes.toByteArray());out.getFD().sync();}Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);com.vandorlabs.persistence.JournalFiles.syncDirectory(target.getParent());File evidence=new File(System.getProperty("vandorlabs.reprolab"),"scoped-split-evidence.nbt");try(FileOutputStream out=new FileOutputStream(evidence)){out.write(bytes.toByteArray());out.getFD().sync();}com.vandorlabs.persistence.JournalFiles.syncDirectory(evidence.toPath().getParent());}
    private static BlockPos position(NBTTagCompound entity){NBTTagList p=entity.getTagList("Pos",6);return new BlockPos(p.getDoubleAt(0),p.getDoubleAt(1),p.getDoubleAt(2));}
    private static EntityGroundVehicle craft(UUID id){Entity e=world.getEntityFromUuid(id);return e instanceof EntityGroundVehicle?(EntityGroundVehicle)e:null;}
    private static NBTTagCompound evidence(EntityGroundVehicle c){NBTTagCompound n=VehicleScopedSplitRecoveryChecks.evidence(c);n.setBoolean("Hover",c.hover);n.setDouble("HoverTarget",c.hoverTarget);NBTTagList arms=new NBTTagList();for(Map.Entry<BlockPos,net.minecraft.tileentity.TileEntity> entry:c.view.tiles.entrySet())if(entry.getValue() instanceof GearTileEntity){GearTileEntity a=(GearTileEntity)entry.getValue();NBTTagCompound row=new NBTTagCompound();row.setLong("Cell",entry.getKey().toLong());row.setDouble("Phase",a.progress());row.setBoolean("Target",a.target());arms.appendTag(row);}n.setTag("Arms",arms);return n;}
    /** Read-only and identity keyed: the final world-owned instance must have its own evidence. */
    @SubscribeEvent public void joined(EntityJoinWorldEvent event){if(!active()||event.getWorld().isRemote||!(event.getEntity() instanceof EntityGroundVehicle))return;EntityGroundVehicle c=(EntityGroundVehicle)event.getEntity();if(c.structure!=null&&c.view!=null){need(JOINED.size()<24||JOINED.containsKey(c),"bounded join observer");if(!JOINED.containsKey(c))JOINED.put(c,evidence(c));}}
    public static void arm(WorldServer w,UUID id){need(active()&&!armed&&!phase().startsWith("verify"),"one actual release admission");register();world=w;armed=true;
        VehicleCouplingTransfer.fault=point->{try{
            if(point.equals("journal")){
                NBTTagCompound record=((NBTTagCompound)field(hold(),"record")).copy();EntityGroundVehicle c=craft(id);need(c!=null&&c.structure.write().equals(record.getCompoundTag("Before").getCompoundTag("Craft")),"exact original live Source at real journal preflight");need(c.couplerAssociationGeneration()==null,"nullable original owner not synthetic generation");
                UUID a=EntityGroundVehicle.readCouplerGeneration(record.getCompoundTag("After")),b=EntityGroundVehicle.readCouplerGeneration(record.getCompoundTag("Detached"));need(a!=null&&b!=null&&!a.equals(b),"two actual independent output generations");
                metadata=new NBTTagCompound();metadata.setTag("Journal",record);metadata.setTag("BeforeEvidence",evidence(c));metadata.setTag("BeforeArticulation",cachedArticulation(c));metadata.setLong("JournalTick",w.getTotalWorldTime());metadata.setInteger("OwnedCells",owned(c));saveManual(w,metadata);
                BlockPos parent=position(record.getCompoundTag("Before")),child=position(record.getCompoundTag("Detached"));need((parent.getZ()>>4)!=(child.getZ()>>4)||(parent.getX()>>4)!=(child.getX()>>4),"real output entity chunks differ");write(w,metadata);Set<Chunk> chunks=new LinkedHashSet<>();chunks.add(w.getChunkFromBlockCoords(parent));chunks.add(w.getChunkFromBlockCoords(child));checkpoint(w,chunks);
            }
            if(point.equals("install")){
                NBTTagCompound record=(NBTTagCompound)field(hold(),"record");EntityGroundVehicle a=craft(record.getUniqueId("Vehicle")),b=craft(record.getCompoundTag("Detached").getUniqueId("UUID"));need(a!=null&&b!=null,"both actual scoped outputs installed");metadata.setTag("AfterEvidence",evidence(a));metadata.setTag("DetachedEvidence",evidence(b));write(w,metadata);
                if(phase().endsWith("rollback-partial")){checkpoint(w,Collections.singleton(w.getChunkFromBlockCoords(b.getPosition())));throw new IllegalStateException("fixture caught failure after real detached chunk save");}
                if(phase().endsWith("split-partial")){checkpoint(w,Collections.singleton(w.getChunkFromBlockCoords(b.getPosition())));halt(w,point);}
            }
            if(point.equals("rollback")&&phase().endsWith("rollback-partial")){checkpoint(w,Collections.singleton(w.getChunkFromBlockCoords(position(metadata.getCompoundTag("Journal").getCompoundTag("Before")))));halt(w,point);}
            if(point.equals("publish")&&phase().endsWith("committed")){need(((NBTTagCompound)field(hold(),"record")).getBoolean("Committed"),"actual durable committed WAL before crash");halt(w,point);}
        }catch(RuntimeException error){throw error;}catch(Exception error){throw new IllegalStateException(error);}};
    }
    private static void saveManual(WorldServer w,NBTTagCompound data)throws Exception{NBTTagCompound live=ManualRedstoneData.get(w).writeToNBT(new NBTTagCompound());need(!ManualRedstoneData.get(w).entries.isEmpty(),"real transmitter baseline exists");w.getPerWorldStorage().saveAllData();File f=w.getSaveHandler().getMapFileFromName("vandorlabs_manual_redstone");need(f.isFile(),"engine saved actual manual input baseline");try(java.nio.channels.FileChannel channel=java.nio.channels.FileChannel.open(f.toPath(),StandardOpenOption.WRITE)){channel.force(true);}com.vandorlabs.persistence.JournalFiles.syncDirectory(f.toPath().getParent());need(read(f).getCompoundTag("data").equals(live),"saved manual input entries exact");data.setTag("ManualInput",live);}
    private static void checkpoint(WorldServer w,Collection<Chunk> chunks)throws Exception{try(TransferCheckpoint cp=new TransferCheckpoint(w,chunks)){long until=System.nanoTime()+45_000_000_000L;while(!cp.step()){need(System.nanoTime()<until,"real asynchronous chunk checkpoint");Thread.sleep(25);}}}
    private static void halt(WorldServer w,String point)throws Exception{System.out.println("[vandorlabs] scoped-split-crash phase="+phase()+" point="+point+" sameRealJournal/partialIndependentChunks");System.out.flush();try(FileOutputStream out=new FileOutputStream(new File(w.getSaveHandler().getWorldDirectory(),"arm-crash-ready.txt"))){out.write(java.lang.management.ManagementFactory.getRuntimeMXBean().getName().split("@")[0].getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.getFD().sync();}new CountDownLatch(1).await();}
    private static List<EntityGroundVehicle> outputs(WorldServer w){List<EntityGroundVehicle> out=new ArrayList<>();for(Entity e:w.loadedEntityList)if(e instanceof EntityGroundVehicle&&!e.isDead&&e.posX>1850&&e.posX<1950&&e.posZ>1850&&e.posZ<1950)out.add((EntityGroundVehicle)e);out.sort(Comparator.comparing(c->c.getUniqueID().toString()));return out;}
    private static int owned(EntityGroundVehicle c){int count=c.structure.cells.size();for(net.minecraft.tileentity.TileEntity tile:c.view.tiles.values())if(tile instanceof GearTileEntity){GearTileEntity gear=(GearTileEntity)tile;if(gear.payload()!=null&&!gear.payload().materialized())count+=gear.payload().blocks.cells.size();}return count;}
    private static String summary(List<EntityGroundVehicle> out){StringBuilder s=new StringBuilder();for(EntityGroundVehicle c:out)s.append(c.getUniqueID()).append('/').append(c.couplerAssociationGeneration()).append('/').append(c.structure.cells.size()).append("cells ");return s.toString();}
    private static void receipts(List<EntityGroundVehicle> out,boolean scoped){Set<UUID> ids=new HashSet<>(),scopes=new HashSet<>();int chests=0,diamonds=0,arms=0,cells=0;for(EntityGroundVehicle c:out){need(ids.add(c.getUniqueID()),"no duplicate usable UUID/identity");need(!c.transferInProgress&&!c.ownershipBlocked&&c.couplerScopeReady(),"actual world-owned output usable");cells+=owned(c);if(scoped){UUID scope=c.couplerAssociationGeneration();need(scope!=null&&scopes.add(scope),"independent output generations");VehicleArmCouplers.Snapshot observed=VehicleArmCouplers.observe(c);for(VehicleArmCouplers.Head head:observed.heads)need(head.released&&head.association!=null&&head.association.permitsUnpaired(head.association.head,c.getUniqueID(),scope),"released head proof belongs to final owner");need(VehicleArmCouplerPairs.discoverForParking(observed).pairs.isEmpty(),"released outputs do not rejoin");}for(net.minecraft.tileentity.TileEntity tile:c.view.tiles.values()){if(tile instanceof TileEntityChest){chests++;ItemStack item=((TileEntityChest)tile).getStackInSlot(0);need(item.getItem()==Items.DIAMOND,"exact cargo item");diamonds+=item.getCount();}if(tile instanceof GearTileEntity&&((GearTileEntity)tile).payload()!=null&&!((GearTileEntity)tile).payload().materialized())arms++;}}need(chests==2&&diamonds==18&&arms==1&&cells==metadata.getInteger("OwnedCells"),"all scene physical cells/cargo18/captured payload exactly once");}
    private static NBTTagCompound cachedArticulation(EntityGroundVehicle c)throws Exception{NBTTagCompound n=new NBTTagCompound();n.setUniqueId("UUID",c.getUniqueID());double[] yaw=(double[])field(c.articulation,"yaw"),pitch=(double[])field(c.articulation,"pitch");NBTTagList angles=new NBTTagList();for(int i=0;i<yaw.length;i++){NBTTagCompound a=new NBTTagCompound();a.setDouble("Yaw",yaw[i]);a.setDouble("Pitch",pitch[i]);angles.appendTag(a);}n.setTag("Angles",angles);Object[] matrices=(Object[])field(c.articulation,"matrices");NBTTagList poses=new NBTTagList();for(Object value:matrices){com.vandorlabs.physics.RigidTransform t=(com.vandorlabs.physics.RigidTransform)value;NBTTagList row=new NBTTagList();for(double v:t.r)row.appendTag(new NBTTagDouble(v));row.appendTag(new NBTTagDouble(t.x));row.appendTag(new NBTTagDouble(t.y));row.appendTag(new NBTTagDouble(t.z));poses.appendTag(row);}n.setTag("Matrices",poses);return n;}
    /** Same Module rejection order and existing geometry callbacks; no alternate shapes or phase writes. */
    private static NBTTagCompound prepass(EntityGroundVehicle craft,GearTileEntity gear,double next){
        double phase=gear.progress();boolean target=gear.target();VehicleStructure source=craft.structure;
        NBTTagCompound n=new NBTTagCompound();n.setLong("Arm",gear.getPos().toLong());n.setDouble("Phase",phase);n.setDouble("Next",next);n.setBoolean("Operational",gear.isOperational());n.setBoolean("Held",gear.parkingHeld());
        List<net.minecraft.util.math.AxisAlignedBB> old=com.vandorlabs.gear.GearGeometry.boxes(gear,phase),after=com.vandorlabs.gear.GearGeometry.boxes(gear,next);boolean constrained=craft.articulation.constrainsArm(gear.getPos());n.setBoolean("Constrained",constrained);VehiclePose pose=new VehiclePose(craft.posX,craft.posY,craft.posZ,craft.rotationYaw);
        for(int i=0;i<after.size();i++){net.minecraft.util.math.AxisAlignedBB box=after.get(i);if(old.get(i).equals(box)||box.getAverageEdgeLength()==0)continue;net.minecraft.util.math.AxisAlignedBB swept=com.vandorlabs.gear.GearGeometry.swept(gear,i,old.get(i),box,phase,next);List<net.minecraft.util.math.AxisAlignedBB> foreign=constrained?Collections.emptyList():com.vandorlabs.gear.GearGeometry.foreign(craft.view,gear,swept);
            if(!foreign.isEmpty()){n.setString("Kind","foreign");n.setInteger("Piece",i);n.setTag("Swept",box(swept));n.setTag("Boxes",boxes(foreign));n.setInteger("BoxCount",foreign.size());break;}
            net.minecraft.util.math.AxisAlignedBB at=pose.world(swept,craft.structure.bounds.maxX/2,craft.structure.bounds.maxZ/2);if(!craft.world.isAreaLoaded(new BlockPos(at.minX,at.minY,at.minZ),new BlockPos(at.maxX,at.maxY,at.maxZ),false)){n.setString("Kind","cold");n.setTag("Swept",box(at));break;}List<net.minecraft.util.math.AxisAlignedBB> worldBoxes=craft.world.getCollisionBoxes(craft,at);if(!worldBoxes.isEmpty()){n.setString("Kind","world");n.setInteger("Piece",i);n.setTag("Swept",box(at));n.setTag("Boxes",boxes(worldBoxes));n.setInteger("BoxCount",worldBoxes.size());break;}
        }
        if(!n.hasKey("Kind"))n.setString("Kind","none");need(source==craft.structure&&gear.progress()==phase&&gear.target()==target,"actual prepass replay does not mutate Source/phase/target");return n;
    }
    private static NBTTagList box(net.minecraft.util.math.AxisAlignedBB b){NBTTagList n=new NBTTagList();for(double v:new double[]{b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ})n.appendTag(new NBTTagDouble(v));return n;}
    private static NBTTagList boxes(List<net.minecraft.util.math.AxisAlignedBB> input){NBTTagList n=new NBTTagList();for(int i=0;i<Math.min(8,input.size());i++)n.appendTag(box(input.get(i)));return n;}
    public static boolean verify(WorldServer w,EntityPlayerMP actor)throws Exception{
        world=w;need(++ticks<1200,"bounded normal cold recovery");if(metadata==null){metadata=read(file(w));deadline=System.nanoTime()+60_000_000_000L;}
        NBTTagCompound record=metadata.getCompoundTag("Journal");UUID parent=record.getUniqueId("Vehicle"),oldChild=record.getCompoundTag("Detached").getUniqueId("UUID");w.getChunkFromBlockCoords(position(record.getCompoundTag("Before")));w.getChunkFromBlockCoords(position(record.getCompoundTag("Detached")));
        if(VehicleCouplingTransfer.pendingCount(w)!=0){need(System.nanoTime()<deadline,"ordinary recovery or genuine intent retry retires WAL");return false;}
        boolean second=phase().startsWith("verify2-"),committed=phase().endsWith("committed");List<EntityGroundVehicle> out=outputs(w);int initialCount=second?metadata.getTagList("Stable",10).tagCount():committed?2:1;
        if(!verified){if(out.size()!=initialCount){need(System.nanoTime()<deadline,"initial actual scene owner count: "+summary(out));return false;}
            need(read(w.getSaveHandler().getMapFileFromName("vandorlabs_manual_redstone")).getCompoundTag("data").equals(metadata.getCompoundTag("ManualInput")),"actual saved manual input unchanged");
            for(EntityGroundVehicle c:out){NBTTagCompound expected;if(second){expected=null;NBTTagList list=metadata.getTagList("Stable",10);for(int i=0;i<list.tagCount();i++)if(c.getUniqueID().equals(list.getCompoundTagAt(i).getUniqueId("UUID")))expected=list.getCompoundTagAt(i);need(expected!=null,"required stable final owner identity");}else expected=metadata.getCompoundTag(committed?(c.getUniqueID().equals(parent)?"AfterEvidence":"DetachedEvidence"):"BeforeEvidence");NBTTagCompound joined=JOINED.get(c);need(joined!=null,"final actual world-owned instance observed before motion");need(joined.equals(expected),"exact Source/scope/pose/phase/target at pre-motion join; differing keys="+difference(expected,joined));}
            receipts(out,second||committed);if(!second&&!committed){EntityGroundVehicle c=out.get(0);need(c.getUniqueID().equals(parent)&&c.couplerAssociationGeneration()==null&&craft(oldChild)==null,"initial nullable original rollback; detached unusable");metadata.setBoolean("OriginalRollbackVerified",true);metadata.setTag("RecoveredOriginal",JOINED.get(c));write(w,metadata);System.out.println("[vandorlabs] scoped-split-original-rollback PASS oneUsableOwner/nullScope/exactBeforeSourcePose/actualPendingUnlockRetained");}
            verified=true;if(!second)return false;
        }
        if(!second){
            EntityGroundVehicle originalOwner=craft(parent);if(originalOwner!=null){if(!actor.capabilities.allowFlying||!actor.capabilities.isFlying){actor.capabilities.allowFlying=true;actor.capabilities.isFlying=true;actor.sendPlayerAbilities();}actor.setPositionAndUpdate(originalOwner.posX+2,originalOwner.posY+3,originalOwner.posZ+2);}
            if(out.size()!=2){need(out.size()==1&&!committed&&System.nanoTime()<deadline,"genuine pending unlock produces exactly two usable outputs; all scene owners="+summary(out));return false;}
            receipts(out,true);if(!committed){need(metadata.getBoolean("OriginalRollbackVerified")&&craft(oldChild)==null,"rolled-back detached UUID never becomes usable");boolean retained=false;for(EntityGroundVehicle c:out){retained|=c.getUniqueID().equals(parent);need(!c.getUniqueID().equals(oldChild),"genuine retry uses a fresh detached UUID");UUID scope=c.couplerAssociationGeneration();need(!scope.equals(EntityGroundVehicle.readCouplerGeneration(record.getCompoundTag("After")))&&!scope.equals(EntityGroundVehicle.readCouplerGeneration(record.getCompoundTag("Detached"))),"new actual retry cannot reuse failed staged generations");}need(retained,"retry retains original parent UUID");metadata.setBoolean("GenuinePendingUnlockRetried",true);}
            boolean allSafe=true;NBTTagList candidate=new NBTTagList(),articulation=new NBTTagList();
            for(EntityGroundVehicle c:out){actor.setPositionAndUpdate(c.posX+2,c.posY+3,c.posZ+2);Map<BlockPos,Double> proposed=new LinkedHashMap<>();for(Map.Entry<BlockPos,net.minecraft.tileentity.TileEntity> entry:c.view.tiles.entrySet())if(entry.getValue() instanceof GearTileEntity){GearTileEntity gear=(GearTileEntity)entry.getValue();double next=com.vandorlabs.gear.core.GearMotion.advance(gear.progress(),gear.target(),1,GearTileEntity.ANIMATION_TICKS);if(next!=gear.progress())proposed.put(entry.getKey(),next);}
                if(!proposed.isEmpty()){VehicleStructure original=c.structure;boolean permits=c.articulation.permitsPose(c.view,proposed),ready=c.collisionCache.readyForCanopyPose(c.view,proposed);need(original==c.structure,"diagnostic readiness leaves Source identity unchanged");boolean blocked=false;NBTTagList witnesses=new NBTTagList();for(Map.Entry<BlockPos,Double> step:proposed.entrySet()){GearTileEntity gear=(GearTileEntity)c.view.tiles.get(step.getKey());NBTTagCompound witness=prepass(c,gear,step.getValue());witnesses.appendTag(witness);blocked|=!"none".equals(witness.getString("Kind"));}metadata.setTag("Prepass",witnesses);allSafe&=!permits||blocked;if(ticks%50==0)System.out.println("[vandorlabs] scoped-split-lastvalid owner="+c.getUniqueID()+" next="+proposed+" permits="+permits+" ready="+ready+" currentPrepassBlocked="+blocked+" witness="+metadata.getTag("Prepass")+" obstruction="+c.articulation.lastObstruction+" cacheWaits="+c.collisionCache.waits()+" cacheFailure="+c.collisionCache.failure());}
                candidate.appendTag(evidence(c));articulation.appendTag(cachedArticulation(c));
            }
            metadata.setTag("ObservedOwners",candidate);metadata.setTag("Articulation",articulation);
            if(!candidate.equals(lastStable)){lastStable=candidate;stableSince=w.getTotalWorldTime();}
            if(!allSafe||w.getTotalWorldTime()-stableSince<50){if(System.nanoTime()>=deadline)write(w,metadata);need(System.nanoTime()<deadline,"actual endpoint or witnessed safe refusal stable50ticks");return false;}
            metadata.setTag("Stable",candidate);metadata.setLong("StableWorldTicks",w.getTotalWorldTime()-stableSince);write(w,metadata);
        }else receipts(out,true);
        Set<Chunk> chunks=new LinkedHashSet<>();for(EntityGroundVehicle c:out)chunks.add(w.getChunkFromBlockCoords(c.getPosition()));chunks.add(w.getChunkFromBlockCoords(position(record.getCompoundTag("Before"))));chunks.add(w.getChunkFromBlockCoords(position(record.getCompoundTag("Detached"))));checkpoint(w,chunks);
        System.out.println("[vandorlabs] arm-durable-recovery PASS "+phase()+" checks="+checks+" readOnlyFinalIdentityJoin/SourceScopePose/cargo18/twoIndependentReleasedOwners/stableCheckpoint originalRollback="+metadata.getBoolean("OriginalRollbackVerified")+" genuineRetry="+metadata.getBoolean("GenuinePendingUnlockRetried"));return true;
    }
    private static Set<String> difference(NBTTagCompound a,NBTTagCompound b){Set<String> keys=new TreeSet<>(a.getKeySet());keys.addAll(b.getKeySet());keys.removeIf(k->Objects.equals(a.getTag(k),b.getTag(k)));return keys;}
